END FUNCTION uclchem_sparse_jacobian_nnz
SUBROUTINE uclchem_sparse_jacobian_pattern(colptr, rowind) BIND(C, name="uclchem_sparse_jacobian_pattern")
    INTEGER(c_int), INTENT(OUT) :: colptr(*), rowind(*)
    INTEGER :: i
    DO i = 1, jac_neq + 1
        colptr(i) = INT(jac_col_ptr(i), c_int)
    END DO
    DO i = 1, jac_nnz
        rowind(i) = INT(jac_row_ind(i), c_int)
    END DO
END SUBROUTINE uclchem_sparse_jacobian_pattern
